import { describe, expect, it } from "vitest";
import {
  InvalidSlugError,
  SLUG_MAX_LENGTH,
  assertValidSlug,
  isReservedSlug,
  isValidSlug,
  projectKeyFromName,
  slugify,
  uniqueSlug,
} from "@/lib/slug";

describe("slugify", () => {
  it("lowercases, strips punctuation and collapses separators", () => {
    expect(slugify("Taskflow Core Team")).toBe("taskflow-core-team");
    expect(slugify("  Hello,   World!  ")).toBe("hello-world");
    expect(slugify("a---b")).toBe("a-b");
  });

  it("strips diacritics rather than dropping the letter", () => {
    expect(slugify("Café Münster")).toBe("cafe-munster");
  });

  it("never emits a leading or trailing hyphen", () => {
    expect(slugify("--edge--")).toBe("edge");
    expect(slugify("!!!")).toBe("");
  });

  it("respects the maximum length", () => {
    expect(slugify("x".repeat(200)).length).toBeLessThanOrEqual(SLUG_MAX_LENGTH);
  });
});

describe("slug validation", () => {
  it("accepts well-formed slugs and rejects malformed ones", () => {
    expect(isValidSlug("acme-corp")).toBe(true);
    expect(isValidSlug("a")).toBe(false);
    expect(isValidSlug("Acme")).toBe(false);
    expect(isValidSlug("acme--corp")).toBe(false);
    expect(isValidSlug("-acme")).toBe(false);
  });

  it("knows the reserved slugs", () => {
    expect(isReservedSlug("settings")).toBe(true);
    expect(isReservedSlug("acme")).toBe(false);
  });

  it("assertValidSlug throws InvalidSlugError for malformed and reserved values", () => {
    expect(() => assertValidSlug("acme-corp")).not.toThrow();
    expect(() => assertValidSlug("Acme")).toThrow(InvalidSlugError);
    expect(() => assertValidSlug("billing")).toThrow(InvalidSlugError);
  });
});

describe("uniqueSlug", () => {
  it("returns the base slug when it is free", () => {
    expect(uniqueSlug("Acme Corp", [])).toBe("acme-corp");
  });

  it("appends an incrementing suffix on collision", () => {
    expect(uniqueSlug("Acme Corp", ["acme-corp"])).toBe("acme-corp-2");
    expect(uniqueSlug("Acme Corp", ["acme-corp", "acme-corp-2"])).toBe("acme-corp-3");
  });

  it("skips reserved slugs", () => {
    expect(uniqueSlug("Billing", [])).toBe("billing-2");
  });

  it("falls back to a usable base when the input slugifies to nothing", () => {
    expect(uniqueSlug("!!!", [])).toBe("item");
  });
});

describe("projectKeyFromName", () => {
  it("uses initials for multi-word names", () => {
    expect(projectKeyFromName("Mobile App Redesign")).toBe("MAR");
  });

  it("uses a prefix for single-word names", () => {
    expect(projectKeyFromName("Platform")).toBe("PLA");
  });

  it("always returns a non-empty uppercase key", () => {
    expect(projectKeyFromName("###")).toBe("TASK");
  });
});
/**
 * Presentation helpers for the audit trail.
 *
 * `ActivityEvent.summary` is written by the service layer and is authoritative;
 * these helpers only supply the verb chip and the day grouping the feed and the
 * per-issue panel both render, so the two views never disagree about what a
 * day boundary is.
 */
import type { ActivityAction, ActivityEvent, ActivityGroup } from "@/types/activity";

export const ACTIVITY_LABELS: Readonly<Record<ActivityAction, string>> = {
  "organization.updated": "updated the organization",
  "project.created": "created a project",
  "project.updated": "updated a project",
  "project.archived": "archived a project",
  "project.restored": "restored a project",
  "issue.created": "created an issue",
  "issue.updated": "updated an issue",
  "issue.status_changed": "changed status",
  "issue.assigned": "assigned an issue",
  "issue.archived": "archived an issue",
  "issue.restored": "restored an issue",
  "comment.created": "commented",
  "comment.updated": "edited a comment",
  "comment.deleted": "deleted a comment",
  "member.invited": "invited a member",
  "member.joined": "joined the organization",
  "member.role_changed": "changed a role",
  "member.removed": "removed a member",
  "billing.plan_changed": "changed the plan",
  "flag.toggled": "toggled a feature flag",
};

export function activityLabel(action: ActivityAction): string {
  return ACTIVITY_LABELS[action] ?? action;
}

/** The calendar day an event belongs to, in UTC (`YYYY-MM-DD`). */
export function activityDay(event: ActivityEvent): string {
  return event.occurredAt.slice(0, 10);
}

/**
 * Groups a flat event list into the day buckets `ActivityFeed` consumes,
 * newest day first and newest event first within a day.
 */
export function groupEventsByDay(
  events: readonly ActivityEvent[],
): readonly ActivityGroup[] {
  const byDay = new Map<string, ActivityEvent[]>();

  for (const event of events) {
    const day = activityDay(event);
    const bucket = byDay.get(day) ?? [];
    bucket.push(event);
    byDay.set(day, bucket);
  }

  return [...byDay.entries()]
    .sort(([a], [b]) => b.localeCompare(a))
    .map(([day, bucket]) => ({
      day,
      events: [...bucket].sort((a, b) =>
        b.occurredAt.localeCompare(a.occurredAt),
      ),
    }));
}
/**
 * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit
 */
import { createHmac } from "node:crypto";
import { wouldExceedLimit } from "@/config/plan-limits";
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { requireFound, webhookResource } from "./_support";
import type {
  CreateWebhookInput,
  DeleteWebhookInput,
  UpdateWebhookInput,
} from "@/schemas/webhook";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";

/** Length in bytes of a generated endpoint signing secret. */
const SECRET_BYTES = 32;

export async function listWebhooks(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly WebhookEndpointRow[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "webhook:manage", webhookResource(orgId, null));
  return webhookRepo.listEndpoints(orgId);
}

/**
 * Creating an endpoint is gated twice: the `webhooks` flag has to be on for
 * the org's plan, and the plan's endpoint count must have room. A secret is
 * minted here and never regenerated — rotating it means deleting the endpoint.
 */
export async function createWebhook(
  actor: Actor,
  input: CreateWebhookInput,
): Promise<WebhookEndpointRow> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, null));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (!isEnabled("webhooks", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {
    throw new Error("Outgoing webhooks are not included in this plan");
  }

  const used = await webhookRepo.countEndpoints(input.orgId);
  if (wouldExceedLimit(org.plan, "webhooks", used)) {
    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);
  }

  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));
}

export async function updateWebhook(
  actor: Actor,
  input: UpdateWebhookInput,
): Promise<WebhookEndpointRow> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
  return webhookRepo.updateEndpoint(input);
}

export async function deleteWebhook(
  actor: Actor,
  input: DeleteWebhookInput,
): Promise<void> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
  await webhookRepo.deleteEndpoint(input.orgId, input.webhookId);
}

/**
 * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes
 * this from the same secret — it is the only thing proving the delivery came
 * from Taskflow, so the payload string must be signed byte-for-byte as sent.
 */
export function signPayload(secret: string, payload: string): string {
  return createHmac("sha256", secret).update(payload, "utf8").digest("hex");
}

/**
 * Fans domain events out into the delivery table. Each org's endpoints
 * declare which event types they want, so an endpoint only ever receives what
 * it subscribed to; the job drains the rows afterwards.
 */
export function registerWebhookListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("webhook.delivery_requested", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        payload.eventType,
        JSON.stringify(payload.payload),
      );
    }),
    subscribe("issue.created", async (payload) => {
      await enqueueForOrg(payload.orgId, "issue.created", JSON.stringify(payload));
    }),
    subscribe("issue.status_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "issue.status_changed",
        JSON.stringify(payload),
      );
    }),
    subscribe("comment.created", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "comment.created",
        JSON.stringify(payload),
      );
    }),
    subscribe("billing.plan_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "billing.plan_changed",
        JSON.stringify(payload),
      );
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

async function enqueueForOrg(
  orgId: OrgId,
  eventType: string,
  payload: string,
): Promise<void> {
  const endpoints = await webhookRepo.listEndpoints(orgId);

  for (const endpoint of endpoints) {
    if (!endpoint.enabled) continue;

    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];
    if (!wanted.includes(eventType)) continue;

    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);
  }
}

function flagContextFor(
  actor: Actor,
  plan: FlagContext["plan"],
  overrides: readonly string[],
): FlagContext {
  return {
    orgId: actor.orgId,
    userId: actor.userId,
    plan,
    role: actor.role,
    overrides,
  };
}
