import type { Organization } from "@/types/organization";

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const db = getDb();
  const row = db
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const retired = db
    .select({ org: organizations })
    .from(organizationRetiredSlugs)
    .innerJoin(organizations, eq(organizations.id, organizationRetiredSlugs.orgId))
    .where(and(
      eq(organizationRetiredSlugs.slug, slug),
      gt(organizationRetiredSlugs.retiredAt, retirementCutoff(Date.now())),
      isNull(organizations.archivedAt),
    ))
    .get();
  return retired ? toOrganization(retired.org) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Derive and reserve the slug in the same transaction, including retired URLs.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  return getDb().transaction((tx) => {
    const now = Date.now();
    const slug = uniqueSlug(input.slug, takenSlugs(tx, input.slug, now));
    const stamp = toIsoTimestamp(new Date(now));

    // Remove an expired retirement before assigning this URL to a new org.
    tx.delete(organizationRetiredSlugs)
      .where(eq(organizationRetiredSlugs.slug, slug)).run();

    const row = tx
      .insert(organizations)
      .values({
        id: newId(),
        name: input.name,
        slug,
        ownerId,
        plan: input.plan,
        logoUrl: null,
        trialEndsAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    return toOrganization(row);
  }, { behavior: "immediate" });
}

/** Settings and profile patch; URL changes go through `renameOrgSlug`. */
export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  return takenSlugs(getDb(), prefix, Date.now());
}

function retirementCutoff(now: number): string {
  return new Date(now - ORG_SLUG_HOLD_DAYS * 24 * 60 * 60 * 1000).toISOString();
}

function takenSlugs(
  db: Pick<Db, "select">,
  prefix: string,
  now: number,
): readonly string[] {
  // `uniqueSlug` truncates long bases before appending a suffix.
  const pattern = `${prefix.slice(0, SLUG_MAX_LENGTH - 5)}%`;
  const rows = db
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, pattern))
    .all();
  const retired = db
    .select({ slug: organizationRetiredSlugs.slug })
    .from(organizationRetiredSlugs)
    .where(and(
      like(organizationRetiredSlugs.slug, pattern),
      gt(organizationRetiredSlugs.retiredAt, retirementCutoff(now)),
    ))
    .all();
  return [...rows, ...retired].map((row) => row.slug);
}

/** Atomically claim the chosen URL and retire the replaced URL. */
export async function renameOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<{ organization: Organization; from: string }> {
  assertValidSlug(slug);
  return getDb().transaction((tx) => {
    const current = tx.select().from(organizations)
      .where(eq(organizations.id, orgId)).get();
    if (!current) throw new Error(`Organization ${orgId} not found`);
    if (current.slug === slug) {
      return { organization: toOrganization(current), from: current.slug };
    }

    const now = Date.now();
    const occupied = tx.select({ id: organizations.id }).from(organizations)
      .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId))).get();
    const held = tx.select().from(organizationRetiredSlugs)
      .where(and(
        eq(organizationRetiredSlugs.slug, slug),
        ne(organizationRetiredSlugs.orgId, orgId),
        gt(organizationRetiredSlugs.retiredAt, retirementCutoff(now)),
      )).get();
    if (occupied || held) throw new InvalidSlugError(slug, "is unavailable");

    tx.delete(organizationRetiredSlugs)
      .where(eq(organizationRetiredSlugs.slug, slug)).run();
    const retired = { slug: current.slug, orgId, retiredAt: toIsoTimestamp(new Date(now)) };
    tx.insert(organizationRetiredSlugs).values(retired)
      .onConflictDoUpdate({ target: organizationRetiredSlugs.slug, set: retired }).run();

    const updated = tx.update(organizations)
      .set({ slug, updatedAt: toIsoTimestamp(new Date(now)) })
      .where(eq(organizations.id, orgId)).returning().get();
    return { organization: toOrganization(updated), from: current.slug };
  }, { behavior: "immediate" });
}
  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));
  assertValidSlug(input.slug);

  requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const { organization, from } = await orgRepo.renameOrgSlug(input.orgId, input.slug);
  if (from === organization.slug) return organization;

  await emit("organization.slug_changed", {
    ...envelope(input.orgId, actor.userId),
    from,
    to: organization.slug,
  });

  return organization;
}

